using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient = new();

    [Description("Searches the web for the given query and returns a list of relevant result snippets. Use this to gather information about a topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);

        try
        {
            // Use a web search API (DuckDuckGo instant answer API as a free option)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadFromJsonAsync<JsonElement>();

            var results = new List<string>();

            // Extract abstract if available
            var abstractText = json.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                var source = json.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            // Extract related topics
            if (json.TryGetProperty("RelatedTopics", out var relatedTopics))
            {
                foreach (var topic in relatedTopics.EnumerateArray())
                {
                    if (results.Count >= maxResults) break;

                    if (topic.TryGetProperty("Text", out var text) &&
                        !string.IsNullOrWhiteSpace(text.GetString()))
                    {
                        results.Add(text.GetString()!);
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try rephrasing the search query.";
            }

            return string.Join("\n\n", results.Select((r, i) => $"Result {i + 1}: {r}"));
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

using System.ComponentModel;

namespace ResearchAgent.Tools;

public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];

    public IReadOnlyList<Note> Notes => _notes;

    [Description("Saves a research note with a title and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short title summarizing the note")] string title,
        [Description("The detailed content of the note")] string content)
    {
        var note = new Note(title, content, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note saved: '{title}' (Total notes: {_notes.Count})";
    }

    [Description("Lists all saved research notes by title.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n.Title}"));
    }

    [Description("Retrieves the full content of a saved note by its number (1-based index).")]
    public string GetNote([Description("The 1-based index of the note to retrieve")] int noteNumber)
    {
        if (noteNumber < 1 || noteNumber > _notes.Count)
            return $"Invalid note number. There are {_notes.Count} notes (use 1 to {_notes.Count}).";

        var note = _notes[noteNumber - 1];
        return $"## {note.Title}\n{note.Content}\n\n(Saved at {note.SavedAt:u})";
    }
}

public sealed record Note(string Title, string Content, DateTime SavedAt);

