using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

// Register tools as singletons so the agent retains state across iterations
builder.Services.AddSingleton<WebSearchTool>();
builder.Services.AddSingleton<NoteTakingTool>();

// Register the chat client via MEAI abstraction
builder.Services.AddChatClient(chatBuilder =>
{
    var apiKey = builder.Configuration["AI:ApiKey"]
        ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
        ?? throw new InvalidOperationException(
            "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

    var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

    return chatBuilder
        .UseOpenAIChatClient(modelId, apiKey: apiKey);
});

var host = builder.Build();

// Resolve services
var chatClient = host.Services.GetRequiredService<IChatClient>();
var webSearch = host.Services.GetRequiredService<WebSearchTool>();
var noteTaking = host.Services.GetRequiredService<NoteTakingTool>();

// Build AI function tools from the tool instances
var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(noteTaking.SaveNote),
    AIFunctionFactory.Create(noteTaking.ListNotes),
    AIFunctionFactory.Create(noteTaking.GetNote),
};

// Create the agent using Microsoft Agent Framework
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using multiple queries
        2. Taking notes on key findings as you discover them
        3. After gathering enough information, producing a comprehensive summary

        Research strategy:
        - Start with broad searches, then narrow down to specific aspects
        - Save important findings as notes with descriptive titles
        - Search at least 3 different angles of the topic
        - After researching, compile your notes into a final summary
        """,
    Tools = tools,
};

// Get the research topic
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║      AI Research Agent (MAF)         ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║ Powered by Microsoft Agent Framework ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(" ", args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine() ?? "quantum computing";
}

Console.WriteLine($"\nResearching: {topic}");
Console.WriteLine(new string('─', 50));

// Run the agent with iteration limits
var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

Console.WriteLine("\n🔍 Agent is researching...\n");

string? finalResponse = null;

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        finalResponse = message.Text;
        Console.Write(message.Text);
    }
}

Console.WriteLine();
Console.WriteLine(new string('─', 50));

// Display collected notes
if (noteTaking.Notes.Count > 0)
{
    Console.WriteLine($"\n📝 Research Notes Collected ({noteTaking.Notes.Count}):");
    foreach (var note in noteTaking.Notes)
    {
        Console.WriteLine($"  • {note.Title}");
    }
}

Console.WriteLine("\n✅ Research complete.");

